p5.RendererGL.prototype._setAttributeDefaults = function(pInst) {
  // See issue #3850, safer to enable AA in Safari
  const applyAA = navigator.userAgent.toLowerCase().includes('safari');
  const defaults = {
    alpha: true,
    depth: true,
    stencil: true,
    antialias: applyAA,
    premultipliedAlpha: false,
    preserveDrawingBuffer: true,
    perPixelLighting: true
  };
  if (pInst._glAttributes === null) {
    pInst._glAttributes = defaults;
  } else {
    pInst._glAttributes = Object.assign(defaults, pInst._glAttributes);
  }
  return;
};

p5.RendererGL.prototype._initContext = function() {
  try {
    this.drawingContext =
      this.canvas.getContext('webgl', this._pInst._glAttributes) ||
      this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
    if (this.drawingContext === null) {
      throw new Error('Error creating webgl context');
    } else {
      const gl = this.drawingContext;
      gl.enable(gl.DEPTH_TEST);
      gl.depthFunc(gl.LEQUAL);
      gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
      this._viewport = this.drawingContext.getParameter(
        this.drawingContext.VIEWPORT
      );
    }
  } catch (er) {
    throw er;
  }
};

//This is helper function to reset the context anytime the attributes
//are changed with setAttributes()

p5.RendererGL.prototype._resetContext = function(options, callback) {
  const w = this.width;
  const h = this.height;
  const defaultId = this.canvas.id;
  const isPGraphics = this._pInst instanceof p5.Graphics;

  if (isPGraphics) {
    const pg = this._pInst;
    pg.canvas.parentNode.removeChild(pg.canvas);
    pg.canvas = document.createElement('canvas');
    const node = pg._pInst._userNode || document.body;
    node.appendChild(pg.canvas);
    p5.Element.call(pg, pg.canvas, pg._pInst);
    pg.width = w;
    pg.height = h;
  } else {
    let c = this.canvas;
    if (c) {
      c.parentNode.removeChild(c);
    }
    c = document.createElement('canvas');
    c.id = defaultId;
    if (this._pInst._userNode) {
      this._pInst._userNode.appendChild(c);
    } else {
      document.body.appendChild(c);
    }
    this._pInst.canvas = c;
  }

  const renderer = new p5.RendererGL(
    this._pInst.canvas,
    this._pInst,
    !isPGraphics
  );
  this._pInst._setProperty('_renderer', renderer);
  renderer.resize(w, h);
  renderer._applyDefaults();

  if (!isPGraphics) {
    this._pInst._elements.push(renderer);
  }

  if (typeof callback === 'function') {
    //setTimeout with 0 forces the task to the back of the queue, this ensures that
    //we finish switching out the renderer
    setTimeout(() => {
      callback.apply(window._renderer, options);
    }, 0);
  }
};
