/* Grunt task to release p5.js on GitHub */

const fs = require('fs');
const req = require('request');

module.exports = function(grunt) {
  grunt.registerTask('release-github', 'Publish a Release on GitHub', function(
    args
  ) {
    // Async Task
    const done = this.async();
    // Keep the release-party ready
    const releaseParty = grunt.config.get('githubReleaser');

    // Prepare the data
    const data = {
      tag_name: '',
      target_commitish: 'master',
      name: '',
      body: '',
      draft: true,
      prerelease: false
    };

    const newTag = require('../../package.json').version;
    data.tag_name = newTag;
    data.name = newTag;

    // Set up vars for requests
    const accessTokenParam = `?access_token=${process.env.GITHUB_TOKEN}`;
    const createURL =
      'https://api.github.com/repos/' +
      releaseParty +
      '/p5.js/releases' +
      accessTokenParam;
    const uploadURL = `https://uploads.github.com/repos/${releaseParty}/p5.js/releases/`;
    let ID = '';
    let count = 0;

    const createReleaseData = {
      url: createURL,
      headers: { 'User-Agent': 'Grunt Task' },
      body: JSON.stringify(data)
    };

    const uploadReleaseData = {
      p5js: ['p5.js', './lib/p5.js', 'application/javascript'],
      p5minjs: ['p5.min.js', './lib/p5.min.js', 'application/javascript'],
      p5soundjs: [
        'p5.sound.js',
        './lib/addons/p5.sound.js',
        'application/javascript'
      ],
      p5soundminjs: [
        'p5.sound.min.js',
        './lib/addons/p5.sound.min.js',
        'application/javascript'
      ],
      p5zip: ['p5.zip', './p5.zip', 'application/zip']
    };

    const uploadAsset = arr => {
      console.log(`Uploading ${arr[0]} ...`);
      fs.createReadStream(arr[1]).pipe(
        req.post(
          {
            url:
              // uploadURL + ID + '/assets' + accessTokenParam + '&name=' + arr[0],
              `${uploadURL}${ID}/assets${accessTokenParam}&name=${arr[0]}`,
            headers: {
              'User-Agent': 'Grunt',
              'Content-Type': arr[2],
              'Content-Length': fs.statSync(arr[1]).size
            }
          },
          (err, resp, body) => {
            if (err) {
              throw err;
            }
            console.log(`Uploaded ${arr[0]}`);
            count++;
            if (count === 5) {
              done();
              console.log('Released on GitHub!\n All done!');
            }
          }
        )
      );
    };

    new Promise((resolve, reject) => {
      // Create the release
      console.log('Posting Release ...');
      req.post(createReleaseData, (error, response, body) => {
        if (error) {
          reject(error);
        }
        resolve(JSON.parse(body).id);
      });
    })
      .then(releaseID => {
        // Upload the Library
        console.log('Uploading Assets ...');
        ID = releaseID;
        // Upload assets
        for (const file in uploadReleaseData) {
          let arr = uploadReleaseData[file];
          uploadAsset(arr);
        }
      })
      .catch(function(err) {
        throw new Error(err);
      });
  });
};

/* Grunt Task to create and publish a p5.js release */
/*
MUST HAVES BEFOREHAND :
* Logged in NPM CLI : Check if you are logged in by "npm whoami"
* High Bandwidth : Lots of things to download and pull and push (~190 MB)
* An environment variable named GITHUB_TOKEN with the value of your Access Token : Make one by going to your Settings->Personal Access Tokens-> New Token. Once you have it, in your shell, run "export GITHUB_TOKEN=<your token here>".
*
* Run with 'grunt release-p5:[increment]' where '[increment]' can be 'patch',
* 'minor', or 'major', corresponding to semver.
*/

const release = require('release-it');

module.exports = function(grunt) {
  // Options for this custom task
  const opts = {
    releaseIt: {
      options: {
        'non-interactive': true,
        'dry-run': false,
        git: {
          requireCleanWorkingDir: false
        },
        verbose: true,
        hooks: {
          'before:init': ['grunt yui && grunt build']
        }
      }
    },
    compress: {
      main: {
        options: {
          archive: 'p5.zip'
        },
        files: [{ cwd: 'lib/', src: ['**/*'], expand: true }]
      }
    }
  };

  // Wrapper around release-it, adapted from 'grunt-release-it'
  grunt.registerTask('release-it', function(increment) {
    const done = this.async();

    const options = this.options();

    options.increment = increment || options.increment;
    options.verbose = grunt.option('verbose') === true || options.verbose;
    options.debug = grunt.option('debug') === true || options.debug;
    options.force = grunt.option('force') === true || options.force;
    options['dry-run'] =
      grunt.option('no-write') === true || options['dry-run'];

    release(options)
      .catch(grunt.fail.warn)
      .finally(done);
  });

  // Register the Release Task
  grunt.registerTask(
    'release-p5',
    'Drafts and Publishes a fresh release of p5.js',
    function(args) {
      // 0. Setup Config
      // Default increment is patch (x.y.z+1)
      opts.releaseIt.options.increment = args;
      // Uncomment to set dry run as true for testing
      // opts.releaseIt.options['dry-run'] = true;
      grunt.config.set('release-it', opts.releaseIt);
      grunt.config.set('compress', opts.compress);
      // Keeping URLs as config vars, so that anyone can change
      // them to add their own, to test if release works or not.
      grunt.config.set('bowerReleaser', 'lmccart');
      grunt.config.set('docsReleaser', 'processing');
      grunt.config.set('githubReleaser', 'processing');

      // 1. Test Suite
      // grunt.task.run('test');

      // 2. Version Bump, Build Library, Docs, Create Commit and Tag, Push to p5.js repo, release on NPM.
      grunt.task.run('release-it');

      // 3. Push the new lib files to the dist repo (to be referred as bower-repo here)
      grunt.task.run('release-bower');

      // 4. Push the docs out to the website
      grunt.task.run('release-docs');

      // 5. Zip the lib folder
      grunt.task.run('compress');

      // 6. Draft a Release for GitHub
      grunt.task.run('release-github');
    }
  );
};

/* Grunt Task to test mocha in a local Chrome instance */

const puppeteer = require('puppeteer');
const util = require('util');
const mapSeries = require('promise-map-series');
const fs = require('fs');
const EventEmitter = require('events');

const mkdir = util.promisify(fs.mkdir);
const writeFile = util.promisify(fs.writeFile);

module.exports = function(grunt) {
  grunt.registerMultiTask('mochaChrome', async function() {
    const done = this.async();

    // Launch Chrome in headless mode
    const browser = await puppeteer.launch({
      headless: true,
      args: ['--no-sandbox']
    });

    try {
      // options here come from `Gruntfile.js` > `mochaConfig.test`
      const options = this.data.options;

      for (const testURL of options.urls) {
        const event = new EventEmitter();
        const page = await browser.newPage();

        try {
          // Using eval to start the test in the browser
          // A 'mocha:end' event will be triggered with test runner end
          await page.evaluateOnNewDocument(`
            addEventListener('DOMContentLoaded', () => {
              if (typeof mocha !== 'undefined') {
                const _mochaRun = mocha.run.bind(mocha);
                mocha.reporter('spec');
                mocha.useColors(true);
                mocha.run = function(fn) {
                  debugger;
                  var runner = _mochaRun(function(stats) {
                    if (typeof fn === 'function')
                      return fn(stats);
                  });

                  runner.on('end', () => {
                    const results = { stats: runner.stats, coverage: window.__coverage__ }
                    fireMochaEvent('mocha:end', results);
                  });

                  return runner;
                };
              }
            });
          `);

          // Pipe console messages from the browser to the terminal
          page.on('console', async msg => {
            const args = await mapSeries(msg.args(), v => v.jsonValue());
            console.log(util.format.apply(util, args));
          });

          // Wait for test end function to be called and emit on the event
          await page.exposeFunction('fireMochaEvent', event.emit.bind(event));

          await new Promise(async (resolve, reject) => {
            // When test end, check if there are any failures and record coverage
            event.on('mocha:end', async results => {
              const { stats, coverage } = results;
              if (stats.failures) {
                reject(stats);
              }
              await saveCoverage(coverage);
              resolve(stats);
            });

            // Nagivate to URL and start test
            await page.goto(testURL);
          });
        } finally {
          await page.close();
        }
      }

      done();
    } catch (e) {
      if (e instanceof Error) {
        done(e);
      } else {
        done(new Error(e));
      }
    } finally {
      await browser.close();
    }
  });
};

async function saveCoverage(cov) {
  if (cov) {
    try {
      await mkdir('./.nyc_output/', { recursive: true });
      await writeFile('./.nyc_output/out.json', JSON.stringify(cov));
    } catch (e) {
      console.error(e);
    }
  }
}

