					new Signal(10).connect(soloA);
					new Signal(20).connect(soloB);
					soloA.solo = true;
					soloB.solo = true;
					soloA.solo = false;
					soloB.solo = false;
				},
				30,
				0.01
			);
		});

		it("can solo and unsolo while keeping previous soloed", () => {
			return ConstantOutput(
				() => {
					const soloA = new Solo().toDestination();
					const soloB = new Solo().toDestination();
					new Signal(10).connect(soloA);
					new Signal(20).connect(soloB);
					soloA.solo = true;
					soloB.solo = true;
					soloB.solo = false;
				},
				10,
				0.01
			);
		});
